function mergeFeeds(feeds: number[][]): number[] {
  // Min-heap of [time, feed, position]. Ties break on feed index so output is stable.
  const heap: [number, number, number][] = [];
  const less = (a: number, b: number) =>
    heap[a][0] < heap[b][0] || (heap[a][0] === heap[b][0] && heap[a][1] < heap[b][1]);
  const swap = (a: number, b: number) => { [heap[a], heap[b]] = [heap[b], heap[a]]; };
  const push = (item: [number, number, number]) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0 && less(i, (i - 1) >> 1)) { swap(i, (i - 1) >> 1); i = (i - 1) >> 1; }
  };
  const pop = (): [number, number, number] => {
    const top = heap[0];
    const last = heap.pop()!;
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && less(l, m)) m = l;
        if (r < heap.length && less(r, m)) m = r;
        if (m === i) break;
        swap(i, m);
        i = m;
      }
    }
    return top;
  };
  feeds.forEach((feed, f) => { if (feed.length) push([feed[0], f, 0]); });
  const out: number[] = [];
  while (heap.length) {
    const [time, f, p] = pop();
    out.push(time);
    if (p + 1 < feeds[f].length) push([feeds[f][p + 1], f, p + 1]);
  }
  return out;
}
